/tmp/opensip-architecture-review-env/bin/python -I -B -c "
import json
R='/tmp/opensip-design-corrections/candidate-subject.v43/docs/coop/artifacts/'
for f in ('resolved-inputs-rust-provider-join.v2.json','delivery-rust-provider-join.v2.json'):
  try:
    d=json.load(open(R+f)); print('==',f, list(d.keys()))
    s=json.dumps(d)
    for k in ('capabilityHandshakeBinding','handshake','identity','expectedIdentity','releaseIdentity'):
      if k in d: print(k, json.dumps(d[k])[:2500])
  except Exception as e: print(f, e)
d=json.load(open(R+'delivery.v2.json'))
ts=d['typescriptSemanticSubstrate']
print('TS identity.handshakeRequired+rest', json.dumps({k:v for k,v in ts['identity'].items() if k not in ('runtimeDescriptor','providerDescriptor','defaultWorkBudgetProfile')})[:2500])
print('TS supervision', json.dumps(ts['supervision'])[:1500])
print('RUST toolchainIdentity', json.dumps(d['rustSemanticSubstrate']['toolchainIdentity'])[:2000])
"

